"180 :   private void findDeclaredNames(Node n, Node parent, Renamer renamer) {
181 :     // Do a shallow traversal, so don't traverse into function declarations,
182 :     // except for the name of the function itself.
183 :     if (parent == null
184 :         || parent.getType() != Token.FUNCTION
185 :         || n == parent.getFirstChild()) {
186 :       if (NodeUtil.isVarDeclaration(n)) {
187 :         renamer.addDeclaredName(n.getString());
188 :       } else if (NodeUtil.isFunctionDeclaration(n)) {
189 :         Node nameNode = n.getFirstChild();
190 :         renamer.addDeclaredName(nameNode.getString());
191 :       }
192 : 
193 :       for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
194 :         findDeclaredNames(c, n, renamer);
195 :       }
196 :     }
