"251 :   private void doStatementNormalizations(NodeTraversal t, Node n, Node parent) {
252 :     if (n.getType() == Token.LABEL) {
253 :       normalizeLabels(n);
254 :     }
255 : 
256 :     // Only inspect the children of SCRIPTs, BLOCKs and LABELs, as all these
257 :     // are the only legal place for VARs and FOR statements.
258 :     if (NodeUtil.isStatementBlock(n) || n.getType() == Token.LABEL) {
259 :       extractForInitializer(n, null, null);
260 :     }
261 : 
262 :     // Only inspect the children of SCRIPTs, BLOCKs, as all these
263 :     // are the only legal place for VARs.
264 :     if (NodeUtil.isStatementBlock(n)) {
265 :       splitVarDeclarations(n);
266 :     }
267 : 
268 :     if (n.getType() == Token.FUNCTION) {
269 :       moveNamedFunctions(n.getLastChild());
270 :     }
