"354 :   private void splitVarDeclarations(Node n) {
355 :     for (Node next, c = n.getFirstChild(); c != null; c = next) {
356 :       next = c.getNext();
357 :       if (c.getType() == Token.VAR) {
358 :         if (assertOnChange && !c.hasChildren()) {
359 :           throw new IllegalStateException("Empty VAR node.");
360 :         }
361 : 
362 :         while (c.getFirstChild() != c.getLastChild()) {
363 :           Node name = c.getFirstChild();
364 :           c.removeChild(name);
365 :           Node newVar = new Node(Token.VAR, name, n.getLineno(), n.getCharno());
366 :           n.addChildBefore(newVar, c);
367 :           reportCodeChange("VAR with multiple children");
368 :         }
369 :       }
370 :     }
371 :   }"

